/* Pseudocode section */

-- Calculate the total revenue generated by employees 

-- SUM(revenue) AS total_revenue

-- who have a Master's degree in "Data Engineering."

-- WHERE education_level LIKE 'Master's Degree' AND
-- field_of_study LIKE '%Data Engineering%'



/*----------------------------------------------------------------------------------------------*/
/*oooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooo*/
/*----------------------------------------------------------------------------------------------*/

/* My implementation & solution section */

/*----------------------------------------------------------------------------------------------*/

/* Viewing table employee_dimension */

-- SELECT *
-- FROM employee_dimension
-- LIMIT 5;

/*----------------------------------------------------------------------------------------------*/

/* Viewing table employee_performance_fact  */

-- SELECT *
-- FROM employee_performance_fact 
-- LIMIT 5;

/*----------------------------------------------------------------------------------------------*/

/* Viewing table qualificationandskills */

-- SELECT *
-- FROM qualificationandskills 
-- LIMIT 5;

/*----------------------------------------------------------------------------------------------*/

/* My solution */

SELECT

    SUM(revenue_generated) AS total_revenue

FROM employee_performance_fact
JOIN qualificationandskills
USING(employee_id)
WHERE education_level = "Master's Degree" AND
field_of_study = 'Data Engineering';

